import React from 'react';
import { Building } from '../../types/game';
import Button from '../ui/Button';
import '../../styles/components/BuildingConstructionMenu.css';

interface BuildingConstructionMenuProps {
  availableBuildings: Building[];
  onBuild: (buildingId: string) => void;
  onClose: () => void;
  playerResources: { gold: number; wood: number; stone: number };
}

const BuildingConstructionMenu: React.FC<BuildingConstructionMenuProps> = ({
  availableBuildings,
  onBuild,
  onClose,
  playerResources
}) => {
  const canAfford = (cost: any = {}) => {
    if (!cost) return false;
    return Object.entries(cost || {}).every(([resource, amount]) => 
      (playerResources[resource as keyof typeof playerResources] || 0) >= (amount as number)
    );
  };

  // Filtrar edificios para excluir el castillo
  const filteredBuildings = (availableBuildings || []).filter(building => 
    !building.is_castle && building.position.x !== 48 && building.position.y !== 48
  );

  return (
    <div className="building-construction-menu">
      <div className="construction-header">
        <h3>Construir Edificios</h3>
        <button onClick={onClose}>×</button>
      </div>

      <div className="construction-content">
        {filteredBuildings.map(building => {
          const buildingCost = building.cost || {};
          return (
            <div key={building.id} className="building-option">
              <div className="building-info">
                <span>{building.name}</span>
                <div className="cost-info">
                  {Object.entries(buildingCost).map(([resource, amount]) => (
                    <span key={resource}>{resource}: {amount}</span>
                  ))}
                </div>
              </div>
              <Button
                onClick={() => onBuild(building.id)}
                disabled={building.built || !canAfford(buildingCost)}
              >
                {building.built ? 'Construido' : 'Construir'}
              </Button>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default BuildingConstructionMenu;
